package module

import("fmt";"strings")
type Manifest struct{Name string `json:"name"`;Version string `json:"version"`;Capabilities []string `json:"capabilities"`;Dependencies []string `json:"dependencies,omitempty"`}
func(m Manifest)Validate()error{m=m.Normalize();if m.Name==""{return fmt.Errorf("module name is required")};if m.Version==""{return fmt.Errorf("module version is required")};seen:=map[string]struct{}{};for _,c:=range m.Capabilities{if c==""{return fmt.Errorf("module %q contains an empty capability",m.Name)};if _,ok:=seen[c];ok{return fmt.Errorf("module %q declares duplicate capability %q",m.Name,c)};seen[c]=struct{}{}};for _,d:=range m.Dependencies{if d==""{return fmt.Errorf("module %q contains an empty dependency",m.Name)};if d==m.Name{return fmt.Errorf("module %q cannot depend on itself",m.Name)}};return nil}
func(m Manifest)Normalize()Manifest{m.Name=strings.TrimSpace(m.Name);m.Version=strings.TrimSpace(m.Version);dedupe:=func(in []string)[]string{seen:=map[string]struct{}{};out:=make([]string,0,len(in));for _,v:=range in{v=strings.TrimSpace(v);if v==""{continue};if _,ok:=seen[v];ok{continue};seen[v]=struct{}{};out=append(out,v)};return out};m.Capabilities=dedupe(m.Capabilities);m.Dependencies=dedupe(m.Dependencies);return m}
